CREATE TABLE "PengaturanSitus" ("kunci" TEXT NOT NULL PRIMARY KEY, "nilai" TEXT NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Pengumuman" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "judul" TEXT NOT NULL, "gambar" TEXT, "tautan" TEXT, "aktif" BOOLEAN NOT NULL DEFAULT true, "mulai" DATETIME, "selesai" DATETIME, "urut" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
